type_bounds:
Types: W: int, H: int, c: List[str]
Ranges: 3 ≤ W ≤ 500, 3 ≤ H ≤ 500, c[i] in {'.', '#', 's', 'g', '*'}
Addtl Info: None

Types: n: int, m: int, a: List[str]
Ranges: 1 ≤ n ≤ 100, m ≤ n, a[i] in {'A', 'B', 'C', 'D'}
Addtl Info: None

Types: N: int, M: int, A: int, grid: List[List[str]]

Ranges: 2 ≤ N, M ≤ 100, 0 ≤ A ≤ 10, grid[i][j] in {'#', '.', 'S', 'G'}

Addtl Info: None

Types: n: int, A: List[Tuple[str, int]]
Ranges: 1 ≤ n ≤ 100,000, 1 ≤ A[i][1] ≤ 10^9, A[i][0] in {'S', 'H', 'C', 'D'}
Addtl Info: None

Types: n: int, p: List[Tuple[str, int]]
Ranges: 1 ≤ n ≤ 1,000, 1 ≤ x_i ≤ 10^6, p_i in {'(', ')'}
Addtl Info: None

Types: H: int, W: int, orchard: List[str]
Ranges: 0 ≤ H ≤ 50, 0 ≤ W ≤ 50, orchard[i]: str of length W
Addtl Info: orchard[i][j] in {' ', '@', '#', '*'}

Types: S: str  
Ranges: 2 ≤ |S| ≤ 2 × 10^5, S consists of {'a', 'b', 'c'}  
Addtl Info: None

Types: S: str
Ranges: 1 ≤ len(S) ≤ 100, S[i] in {'L', 'R', 'U', 'D'}
Addtl Info: None

Types: n: int, s: str, t: str, b: str

Ranges: 0 ≤ n ≤ 15, s in {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'}, t in {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'}, b in {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'}

Addtl Info: n = 0 indicates the end of input, s, t, b are distinct, at most 100 datasets

Types: S: str
Ranges: len(S) = 4, S[i] in {'+', '-'}
Addtl Info: None
